function setSelectionMark(node,on,animate=false){node.replaceChildren();if(on){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M5 12.5 9.5 17 19 7');svg.append(path);node.append(svg)}else node.textContent='+';node.classList.toggle('is-selected',on);if(animate){node.classList.remove('just-selected');void node.offsetWidth;node.classList.add('just-selected')}}
const samples={wonder:[{title:'Contact',year:1997,minutes:150,genre:'Science fiction · Drama',note:'A search for a signal becomes a story about curiosity, belief, and human connection.'},{title:'Moon',year:2009,minutes:97,genre:'Science fiction · Mystery',note:'An intimate space mystery with questions about identity and isolation.'},{title:'The Iron Giant',year:1999,minutes:86,genre:'Animation · Adventure',note:'A warm story about an unlikely friendship and choosing who you want to be.'}],comfort:[{title:'Paddington 2',year:2017,minutes:103,genre:'Comedy · Family',note:'Kindness, comic mishaps, and a neighbourhood coming together.'},{title:'Chef',year:2014,minutes:114,genre:'Comedy · Drama',note:'A fresh start, a food truck, and a father reconnecting with his son.'},{title:'My Neighbor Totoro',year:1988,minutes:86,genre:'Animation · Fantasy',note:'A gentle adventure that finds magic in ordinary childhood moments.'}],suspense:[{title:'Rear Window',year:1954,minutes:112,genre:'Mystery · Thriller',note:'A confined viewpoint makes every detail across the courtyard matter.'},{title:'The Prestige',year:2006,minutes:130,genre:'Drama · Mystery',note:'A rivalry between magicians turns into a puzzle about obsession and sacrifice.'},{title:'Searching',year:2018,minutes:102,genre:'Mystery · Thriller',note:'A missing-person investigation unfolds through the digital traces of a life.'}]};
const form=document.querySelector('#taste-form'),movies=document.querySelector('#movies'),picks=document.querySelector('#picks'),status=document.querySelector('#status'),filter=document.querySelector('#refinement');let active=[];let resultMode="sample";
document.querySelector('#example').addEventListener('click',()=>{movies.value='Interstellar, Arrival, The Martian';if(document.querySelector('#movie-search')){movies.dispatchEvent(new Event('input'));document.querySelector('#movie-search').focus()}else movies.focus()});
function draw(){const rows=active.filter(m=>filter.value!=='short'||m.minutes<120);picks.className='cards';picks.replaceChildren();document.querySelector('#count').textContent=`${rows.length} ${resultMode==="live"?"Qloo":"sample"} picks`;for(const [i,m] of rows.entries()){const article=document.createElement('article');article.className='card';const n=document.createElement('span');n.className='number';n.textContent=String(i+1).padStart(2,'0');n.setAttribute('aria-hidden','true');const body=document.createElement('div'),title=document.createElement('h3'),meta=document.createElement('div'),note=document.createElement('p'),badge=document.createElement('span');title.textContent=m.title;meta.className='meta';meta.textContent=[m.year,m.minutes?`${m.minutes} min`:null,m.genre].filter(Boolean).join(" / ");note.textContent=m.note;badge.className='sample-label';badge.textContent=resultMode==='live'?'Qloo recommendation':'Curated example · not a Qloo match';body.append(title,meta,note,badge);addImdbRating(body,m.title,m.year);const poster=expandedCatalog.find(f=>f.kind==='movie'&&f.title.toLowerCase()===m.title.toLowerCase());if(poster){const img=document.createElement('img');img.className='result-poster';img.src=poster.image;img.alt=`${m.title} poster`;img.width=90;img.height=135;img.loading='lazy';img.referrerPolicy='no-referrer';img.addEventListener('error',()=>{img.hidden=true;article.classList.remove('has-poster')});article.classList.add('has-poster');article.append(img)}article.append(n,body);picks.append(article)}}
form.addEventListener('submit',e=>{e.preventDefault();const titles=movies.value.split(',').map(t=>t.trim()).filter(Boolean);if(!titles.length){movies.setCustomValidity('Enter at least one movie title.');if(document.querySelector('#movie-search')){document.querySelector('#movie-search').focus();document.querySelector('#picker-message').textContent=movies.validationMessage||'Choose one to five films first.';}else movies.reportValidity();return}movies.setCustomValidity('');resultMode='sample';active=samples[new FormData(form).get('mood')];filter.value='all';document.querySelector('#results-heading').textContent='Explore a sample direction.';status.textContent=`You entered: ${titles.join(', ')}. These titles are not matched yet. Your mood selects a fixed sample set.`;document.querySelector('#refine').hidden=false;draw()});movies.addEventListener('input',()=>movies.setCustomValidity(''));filter.addEventListener('change',()=>{draw();status.textContent=resultMode==='live'?'Runtime filter updated. Films without runtime data are excluded from the under-two-hours view.':'Sample runtime filter updated. These remain fixed examples, not live recommendations.'});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'explore_sample_movies',title:'Explore sample movie picks',description:'Update the visible prototype with fixed sample movie picks. This does not call Qloo or generate personalised recommendations.',inputSchema:{type:'object',properties:{movies:{type:'string',maxLength:300},mood:{type:'string',enum:['wonder','comfort','suspense']}},required:['movies','mood'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.movies!=='string'||!input.movies.trim()||input.movies.length>300||!Object.hasOwn(samples,input.mood)||Object.keys(input).some(k=>!['movies','mood'].includes(k)))throw new Error('Provide movie titles and a supported mood.');movies.value=input.movies;form.querySelector(`input[value="${input.mood}"]`).checked=true;form.requestSubmit();return{mode:'fixed_samples',titles:active.map(m=>m.title)}}})).catch(()=>{})}catch{}}

const posterShelf=document.querySelector('#poster-grid');
