if(posterShelf){const films=filmCatalog;const buttons=[];function syncPosters(){const selected=movies.value.split(',').map(x=>x.trim().toLowerCase());buttons.forEach(({button,film,add})=>{const on=selected.includes(film.title.toLowerCase());const wasSelected=button.getAttribute('aria-pressed')==='true';button.setAttribute('aria-pressed',String(on));setSelectionMark(add,on,on&&!wasSelected)})}for(const film of films){const button=document.createElement('button');button.type='button';button.className='poster';button.setAttribute('aria-label',`Add or remove ${film.title} from favourite movies`);button.setAttribute('aria-pressed','false');const art=document.createElement('span');art.className='poster-art';const img=document.createElement('img');img.src=film.image;img.alt=`${film.title} poster`;img.width=200;img.height=300;img.referrerPolicy='no-referrer';img.addEventListener('error',()=>{img.hidden=true;art.style.background='#574432';art.setAttribute('aria-label',`${film.title} artwork unavailable`)});const add=document.createElement('span');add.className='poster-add';add.textContent='+';add.setAttribute('aria-hidden','true');art.append(img,add);const title=document.createElement('span');title.className='poster-title';title.textContent=film.title;const year=document.createElement('span');year.className='poster-year';year.textContent=String(film.year);button.append(art,title,year);addImdbRating(button,film.title,film.year);button.addEventListener('click',()=>{const values=movies.value.split(',').map(x=>x.trim()).filter(Boolean);const at=values.findIndex(x=>x.toLowerCase()===film.title.toLowerCase());if(at>=0)values.splice(at,1);else values.push(film.title);const value=values.join(', ');if(values.length>5||value.length>300){document.querySelector('#poster-status').textContent='Choose up to five favourites. Remove a title to add another.';return}movies.value=value;movies.setCustomValidity('');movies.dispatchEvent(new Event('input'));syncPosters();document.querySelector('#poster-status').textContent=at>=0?`${film.title} removed from your favourites.`:`${film.title} added to your favourites.`});buttons.push({button,film,add});posterShelf.append(button)}movies.addEventListener('input',syncPosters);document.querySelector('#example').addEventListener('click',syncPosters);}

const liveButton=document.querySelector('#live-picks');
if(liveButton){const connection=document.querySelector('#connection-status');let busy=false;
async function checkConnection(){try{const response=await fetch('/api/config',{signal:AbortSignal.timeout(5000)});if(!response.ok)throw new Error();const config=await response.json();liveButton.disabled=!config.liveAvailable;liveButton.textContent=config.liveAvailable?'Find my next film':'Live recommendations pending';connection.textContent=config.liveAvailable?'Qloo access configured. Ready to try live movie matching.':'Waiting for the Qloo key. Sample picks are available below.';if(config.liveAvailable){const notice=document.querySelector('.notice');notice.replaceChildren();const strong=document.createElement('strong'),p=document.createElement('p');strong.textContent='Live movie matching available';p.textContent='Live picks use your favourite movies. Mood matching and the conversational assistant are still being built. The sample button uses fixed examples.';notice.append(strong,p)}}catch{connection.textContent='Live server unavailable. You can still explore sample picks.';liveButton.disabled=true;liveButton.textContent='Live connection unavailable'}}
liveButton.addEventListener('click',async()=>{if(busy)return;const chosenShows=expandedCatalog.filter(f=>f.kind==='show'&&movies.value.split(',').some(t=>t.trim().toLowerCase()===f.title.toLowerCase()));if(chosenShows.length){status.textContent='Live recommendations currently support movies only. Remove TV shows from your favourites, or explore the sample demo.';return}const titles=movies.value.split(',').map(x=>x.trim()).filter(Boolean);if(!titles.length||titles.length>5||titles.some(t=>t.length>120)){movies.setCustomValidity('Enter one to five movie titles, each up to 120 characters.');if(document.querySelector('#movie-search')){document.querySelector('#movie-search').focus();document.querySelector('#picker-message').textContent=movies.validationMessage||'Choose one to five films first.';}else movies.reportValidity();return}movies.setCustomValidity('');busy=true;liveButton.disabled=true;const sampleButton=form.querySelector('button[type="submit"]');sampleButton.disabled=true;liveButton.textContent='Finding your next film…';picks.setAttribute('aria-busy','true');picks.replaceChildren();document.querySelector('#count').textContent='';document.querySelector('#refine').hidden=true;status.textContent='Looking up your favourites and asking Qloo for recommendations…';document.querySelector('#results-heading').textContent='Finding a new direction.';
try{const response=await fetch('/api/recommendations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({titles}),signal:AbortSignal.timeout(30000)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Recommendations are unavailable. Please try again.');if(!Array.isArray(data.movies))throw new Error('The server returned an unexpected result.');resultMode='live';active=data.movies;filter.value='all';draw();document.querySelector('#results-heading').textContent=active.length?'Your next great watch?':'No matches this time.';status.textContent=active.length?`Matched: ${data.matched.map(x=>x.title).join(', ')}. ${data.notice}`:'Qloo returned no new films. Try a different combination of favourites.';document.querySelector('#refine').hidden=!active.some(m=>Number.isFinite(m.minutes));}
catch(error){active=[];picks.className='empty';const p=document.createElement('p');p.textContent=error.name==='TimeoutError'?'That took too long. Please try again.':error.message==='Failed to fetch'?'The server could not be reached. Please try again.':error.message;picks.append(p);document.querySelector('#results-heading').textContent='Let’s try another take.';status.textContent='No live recommendations were generated. You can retry or use sample picks.';}
finally{busy=false;liveButton.disabled=false;sampleButton.disabled=false;liveButton.textContent='Find my next film';picks.setAttribute('aria-busy','false')}});checkConnection();}

const movieSearch=document.querySelector('#movie-search');
if(movieSearch){const options=document.querySelector('#movie-options'),selected=document.querySelector('#selected-movies'),message=document.querySelector('#picker-message');const catalog=[...expandedCatalog,...filmCatalog.filter(f=>!expandedCatalog.some(e=>e.title===f.title)).map(f=>({...f,kind:'movie'}))];const typeFilter=document.querySelector('#catalog-type');const getTitles=()=>movies.value.split(',').map(x=>x.trim()).filter(Boolean);const key=s=>s.toLowerCase().trim();
function selectTitle(title){const values=getTitles();if(values.some(x=>key(x)===key(title))){message.textContent='That film is already in your favourites.';return}if(values.length>=5||[...values,title].join(', ').length>300){message.textContent='Five is the limit. Remove a film to make room.';return}movies.value=[...values,title].join(', ');movies.setCustomValidity('');movieSearch.value='';movies.dispatchEvent(new Event('input'));message.textContent=`${title} added. ${values.length+1} of 5 selected.`;movieSearch.focus()}
function renderOptions(){options.replaceChildren();const query=key(movieSearch.value),values=getTitles().map(key);const matches=catalog.filter(f=>(!typeFilter||typeFilter.value==='all'||f.kind===typeFilter.value)&&`${key(f.title)} ${f.year}`.includes(query)).slice(0,12);for(const film of matches){const button=document.createElement('button');button.type='button';button.className='movie-option';const on=values.includes(key(film.title));button.disabled=on;button.setAttribute('aria-label',`${on?'Selected':'Add'} ${film.title}, ${film.year}`);if(film.image){const img=document.createElement('img');img.src=film.image;img.alt='';img.width=34;img.height=50;img.referrerPolicy='no-referrer';img.addEventListener('error',()=>{img.hidden=true});button.append(img)}else{const icon=document.createElement('span');icon.className='option-monogram';icon.textContent=film.title[0];icon.setAttribute('aria-hidden','true');button.append(icon)}const text=document.createElement('span'),name=document.createElement('strong'),year=document.createElement('small'),action=document.createElement('span');name.textContent=film.title;year.textContent=`${film.year} · ${film.kind==='show'?'TV show':'Movie'}`;text.append(name,year);addImdbRating(text,film.title,film.year);action.className='option-action';setSelectionMark(action,on);action.setAttribute('aria-hidden','true');button.append(text,action);button.addEventListener('click',()=>selectTitle(film.title));options.append(button)}if(query&&!matches.length){const p=document.createElement('p');p.className='hint';p.textContent='No match in this small sample catalog.';options.append(p)}if(query&&!catalog.some(f=>key(f.title)===query)){const manual=document.createElement('button');manual.type='button';manual.className='manual-title';manual.textContent=`Use “${movieSearch.value.trim()}” as a typed title`;manual.addEventListener('click',()=>{const title=movieSearch.value.trim();if(title.includes(',')){message.textContent='Add one film at a time, without commas.';return}selectTitle(title)});options.append(manual);const help=document.createElement('p');help.className='hint';help.textContent='Typed titles are unverified until Qloo is connected.';options.append(help)}}
function renderSelections(){selected.replaceChildren();const values=getTitles();document.querySelector('#selection-count').textContent=`${values.length} / 5`;if(!values.length){const p=document.createElement('p');p.className='selection-empty';p.textContent='Your opening lineup goes here.';selected.append(p)}for(const title of values){const film=catalog.find(f=>key(f.title)===key(title)),chip=document.createElement('div');chip.className='movie-chip';const text=document.createElement('span');text.textContent=title+(film?` · ${film.year}${film.kind==='show'?' · TV':''}`:' · unverified');const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label',`Remove ${title}`);remove.addEventListener('click',()=>{movies.value=getTitles().filter(x=>key(x)!==key(title)).join(', ');movies.setCustomValidity('');movies.dispatchEvent(new Event('input'));message.textContent=`${title} removed.`;movieSearch.focus()});chip.append(text);addImdbRating(chip,title,film?.year);chip.append(remove);selected.append(chip)}renderOptions()}
typeFilter?.addEventListener('change',()=>{message.textContent=typeFilter.value==='show'?'TV shows are for demo selection only; live recommendations currently support movies.':'';renderOptions()});movieSearch.addEventListener('input',()=>{message.textContent='';renderOptions()});movieSearch.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const first=options.querySelector('button:not(:disabled)');if(first)first.click()}if(e.key==='Escape'){movieSearch.value='';renderOptions()}});movies.addEventListener('input',renderSelections);renderSelections();}

const conversation=document.querySelector('#conversation');
if(conversation){const answers=document.querySelector('#conversation-choices'),restart=document.querySelector('#restart-conversation');let preference='',chosenMood='',short=false;const moodNames={wonder:'a sense of wonder',comfort:'something comforting',suspense:'a little suspense'};
function say(text,who='guide'){const bubble=document.createElement('div');bubble.className=`conversation-bubble ${who}`;const label=document.createElement('span');label.className='speaker';label.textContent=who==='guide'?'FILMCOMPASS':'YOU';const p=document.createElement('p');p.textContent=text;bubble.append(label,p);conversation.append(bubble);conversation.scrollTop=conversation.scrollHeight}
function choices(items){answers.replaceChildren();for(const item of items){const button=document.createElement('button');button.type='button';button.textContent=item.label;button.addEventListener('click',()=>{answers.replaceChildren();say(item.label,'you');item.next()});answers.append(button)}}
function start(){preference='';chosenMood='';short=false;conversation.replaceChildren();restart.hidden=true;say('Think of the films you love. What tends to stay with you?');choices(['The mystery','The visuals','The emotional story'].map(label=>({label,next:()=>{preference=label;askMood()}})))}
function askMood(){restart.hidden=false;say('And what sounds good tonight?');choices(Object.entries(moodNames).map(([value,label])=>({label:label[0].toUpperCase()+label.slice(1),next:()=>{chosenMood=value;askTime()}})))}
function askTime(){say('How much time do you have?');choices([{label:'Keep it under two hours',next:()=>finish(true)},{label:'I have time for a longer film',next:()=>finish(false)}])}
function finish(underTwo){short=underTwo;const summary=`You like ${preference.toLowerCase().replace(/^the /,'')}, want ${moodNames[chosenMood]}, and ${short?'prefer a film under two hours':'have room for a longer film'}.`;say(summary+' This demo uses mood and runtime to filter fixed examples; your “what stayed with you” answer is recorded here but does not change the picks yet.');choices([{label:'Show my sample picks',next:()=>showSamples()},{label:'Change my answers',next:()=>start()}])}
function showSamples(){const titles=movies.value.split(',').map(t=>t.trim()).filter(Boolean);if(!titles.length){say('First, choose at least one favourite on the left. Then come back and show your sample picks.');choices([{label:'Show my sample picks',next:()=>showSamples()}]);document.querySelector('#movie-search')?.focus();return}form.querySelector(`input[value="${chosenMood}"]`).checked=true;form.requestSubmit();filter.value=short?'short':'all';draw();status.textContent=`Guided demo: ${moodNames[chosenMood]}${short?', under two hours':''}. These are curated samples, not personalised Qloo or AI results.`;say('Your sample lineup is below. Try another mood or time limit to explore a different set.');choices([{label:'Try another mood',next:()=>askMood()},{label:'Start a new conversation',next:()=>start()}])}
restart.addEventListener('click',start);start();}

async function loadImdbRatings(){try{const response=await fetch('/api/ratings',{cache:'no-store',signal:AbortSignal.timeout(90000)});if(!response.ok)throw new Error('Rating request failed');const data=await response.json();for(const r of data.ratings||[])if(typeof r.title==='string'&&Number.isFinite(r.rating)&&/^tt\d+$/.test(r.id))imdbRatings.set(r.title.toLowerCase()+'|'+r.year,r);ratingsState='ready';}catch{ratingsState='unavailable';}document.querySelectorAll('.imdb-rating').forEach(updateImdbBadge);}
if(typeof fetch==='function')loadImdbRatings();
